#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    long long val;
    int idx;
} Pair;

static int compare_pair(const void *a, const void *b) {
    const Pair *pa = (const Pair *)a;
    const Pair *pb = (const Pair *)b;
    if (pa->val < pb->val) return -1;
    if (pa->val > pb->val) return 1;
    if (pa->idx < pb->idx) return -1;
    if (pa->idx > pb->idx) return 1;
    return 0;
}

static int lower_bound_val(const Pair *arr, int n, long long v) {
    int l = 0, r = n;
    while (l < r) {
        int m = l + (r - l) / 2;
        if (arr[m].val >= v) r = m;
        else l = m + 1;
    }
    return l;
}

static int upper_bound_val(const Pair *arr, int n, long long v) {
    int l = 0, r = n;
    while (l < r) {
        int m = l + (r - l) / 2;
        if (arr[m].val > v) r = m;
        else l = m + 1;
    }
    return l;
}

static int lower_bound_idx(const Pair *arr, int start, int end, int idx) {
    int l = start, r = end;
    while (l < r) {
        int m = l + (r - l) / 2;
        if (arr[m].idx >= idx) r = m;
        else l = m + 1;
    }
    return l;
}

static int upper_bound_idx(const Pair *arr, int start, int end, int idx) {
    int l = start, r = end;
    while (l < r) {
        int m = l + (r - l) / 2;
        if (arr[m].idx > idx) r = m;
        else l = m + 1;
    }
    return l;
}

static int count_range(const Pair *arr, int n, long long val, int idx_low, int idx_high) {
    if (idx_low > idx_high) return 0;
    int start = lower_bound_val(arr, n, val);
    int end = upper_bound_val(arr, n, val);
    if (start >= end) return 0;
    int p1 = lower_bound_idx(arr, start, end, idx_low);
    int p2 = upper_bound_idx(arr, start, end, idx_high);
    return p2 - p1;
}

